class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is PermissionStatus) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    }    else if (value is AssetStatus) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    }    else if (value is HostProbe) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is LiveStartRequest) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is MediaFacts) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is FileTranscribeRequest) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is OverlayConfig) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is PanelState) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is LiveEvent) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is SpeechConfig) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is SpeechInventory) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is CaptureRequest) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is CaptureHandle) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is CaptionLineMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : PermissionStatus.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : AssetStatus.values[value];
      case 131:
        return HostProbe.decode(readValue(buffer)!);
      case 132:
        return LiveStartRequest.decode(readValue(buffer)!);
      case 133:
        return MediaFacts.decode(readValue(buffer)!);
      case 134:
        return FileTranscribeRequest.decode(readValue(buffer)!);
      case 135:
        return OverlayConfig.decode(readValue(buffer)!);
      case 136:
        return PanelState.decode(readValue(buffer)!);
      case 137:
        return LiveEvent.decode(readValue(buffer)!);
      case 138:
        return SpeechConfig.decode(readValue(buffer)!);
      case 139:
        return SpeechInventory.decode(readValue(buffer)!);
      case 140:
        return CaptureRequest.decode(readValue(buffer)!);
      case 141:
        return CaptureHandle.decode(readValue(buffer)!);
      case 142:
        return CaptionLineMessage.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

