/// Returns a broadcast [Stream] of events from the `liveEvents` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<LiveEvent> liveEvents( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel liveEventsChannel =
      EventChannel('dev.flutter.pigeon.tinglang_native_macos.TinglangEvents.liveEvents$instanceName', pigeonMethodCodec);
  return liveEventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as LiveEvent;
  });
}
    
